import Foundation
import Testing

@testable import ExperimentKit
@testable import SteeringKit

/// Chat-template capabilities derived from the pinned template (2026-09-05),
/// checked against bytes the PYTHON engine produced
/// (`Tests/Fixtures/cross-engine/model-capabilities.json`, regenerated by
/// `scripts/regenerate-cross-engine-fixtures.py`).
///
/// The direction is the point: each fixture family is a synthetic template
/// rendered through THIS engine's Jinja (swift-jinja, the engine a loaded
/// tokenizer renders through) and probed by THIS engine's probe; the
/// verdicts, the record hashes, the heuristic fallback, the gate sentences
/// and the template variables each effort becomes must agree with the server
/// byte for byte. Server twin: `Server/tests/test_model_capabilities.py`.
@Suite(.serialized) struct ModelCapabilitiesTests {

    static let qwen = "Qwen/Qwen3-14B"
    static let qwen38 = "Qwen/Qwen3.8-27B"
    static let gemma = "google/gemma-3-27b-it"

    // MARK: - fixture plumbing

    static func load() throws -> [String: Any] {
        let url = CodeResources.compiledCheckoutPath.appending(
            components: "Tests", "Fixtures", "cross-engine", "model-capabilities.json")
        return try #require(
            try JSONSerialization.jsonObject(with: try Data(contentsOf: url)) as? [String: Any])
    }

    static func family(_ fixture: [String: Any], _ label: String) throws -> [String: Any] {
        let families = try #require(fixture["families"] as? [[String: Any]])
        return try #require(families.first { $0["label"] as? String == label })
    }

    static func probe(_ family: [String: Any]) throws -> ModelCapabilities.Record {
        let template = try #require(family["template"] as? String)
        let special = family["specialTokens"] as? [String: String] ?? [:]
        let ids = family["thinkTokenIDs"] as? [String: Int] ?? [:]
        return try ModelCapabilitiesProbe.probe(
            render: ModelCapabilitiesStore.templateRenderer(template, specialTokens: special),
            modelID: "fixture/" + (family["label"] as! String), revision: String(repeating: "0", count: 40),
            thinkTokenID: { ids[$0] },
            architecture: .init(layerCount: 4, hiddenSize: 8, layerTypes: Array(repeating: "full_attention", count: 4)),
            templateSha256: ModelCapabilities.templateSha256(template),
            tokenizerConfigSha256: nil,
            engine: "python-hf-transformers", engineVersion: "fixture",
            probedAt: "2026-09-05T00:00:00Z")
    }

    static func recordFixture(_ fixture: [String: Any], _ label: String) throws -> ModelCapabilities.Record {
        let records = try #require(fixture["records"] as? [[String: Any]])
        let entry = try #require(records.first { $0["label"] as? String == label })
        return try ModelCapabilities.Record.parse(try #require(entry["record"] as? [String: Any]))
    }

    func withTempRoot<T>(_ body: (URL) async throws -> T) async rethrows -> T {
        ExperimentRootOverrideLock.acquire()
        let temp = FileManager.default.temporaryDirectory
            .appending(component: "model-capabilities-\(UUID().uuidString)")
        try? FileManager.default.createDirectory(at: temp, withIntermediateDirectories: true)
        WorkspaceRoot.programmaticOverride = temp
        ExperimentStore.rootOverride = temp
        ModelCapabilities.forgetRegistered()
        defer {
            ExperimentStore.rootOverride = nil
            WorkspaceRoot.programmaticOverride = nil
            ModelCapabilities.forgetRegistered()
            try? FileManager.default.removeItem(at: temp)
            ExperimentRootOverrideLock.release()
        }
        return try await body(temp)
    }

    // MARK: - 1. the probe reproduces the Python engine's verdicts

    @Test func theProbeReproducesEveryFixtureFamily() throws {
        let fixture = try Self.load()
        for family in try #require(fixture["families"] as? [[String: Any]]) {
            let record = try Self.probe(family)
            let expected = try ModelCapabilities.Detected.parse(
                try #require(family["detected"] as? [String: Any]))
            #expect(record.detected == expected, "\(family["label"] ?? "")")
        }
    }

    @Test func theFamiliesReadAsTheyShould() throws {
        let fixture = try Self.load()
        let effort = try Self.probe(try Self.family(fixture, "chatml-effort")).detected
        #expect(effort.systemRole == .systemTurn)
        #expect(effort.thinkingSwitch == .supported && effort.thinkOpenInPrompt == true)
        #expect(effort.effortVariableRead == true)
        // xhigh is the template's DEFAULT and still reads as accepted.
        #expect(effort.effortLevels == ["low": .accepted, "medium": .accepted, "high": .rejected, "xhigh": .accepted])
        #expect(effort.thinkTokens == .init(open: 11, close: 12))
        let switchOnly = try Self.probe(try Self.family(fixture, "chatml-switch")).detected
        #expect(switchOnly.thinkOpenInPrompt == false && switchOnly.effortVariableRead == false)
        #expect(Set(switchOnly.effortLevels!.values) == [.ignored])
        let gemma = try Self.probe(try Self.family(fixture, "gemma-fold")).detected
        #expect(gemma.systemRole == .foldedIntoUser && gemma.foldSeparator == "\n\n")
        #expect(gemma.thinkingSwitch == .unsupported && gemma.effortLevels == nil)
        let refused = try Self.probe(try Self.family(fixture, "system-refused")).detected
        #expect(refused.systemRole == .unsupported)
        #expect(refused.systemRoleDetail?.contains("raises") == true)
    }

    @Test func aTemplateThatDropsTheSystemTurnIsUnsupported() throws {
        let template = "{% for m in messages %}{% if m.role != 'system' %}<{{ m.role }}>{{ m.content }}</{{ m.role }}>{% endif %}{% endfor %}{% if add_generation_prompt %}<assistant>{% endif %}"
        let record = try ModelCapabilitiesProbe.probe(
            render: ModelCapabilitiesStore.templateRenderer(template),
            modelID: "x/drops", revision: nil, engineVersion: "test")
        #expect(record.detected.systemRole == .unsupported)
        #expect(record.detected.systemRoleDetail?.contains("drops") == true)
        #expect(throws: ModelCapabilities.RecordError.self) {
            try ModelCapabilitiesProbe.probe(
                render: ModelCapabilitiesStore.templateRenderer("{{ raise_exception('no') }}"),
                modelID: "x/broken", revision: nil, engineVersion: "test")
        }
    }

    // MARK: - 2. the record: hash, schema, files, overrides

    @Test func theRecordHashAndHeuristicsAreThePythonEnginesByteForByte() throws {
        let fixture = try Self.load()
        for entry in try #require(fixture["records"] as? [[String: Any]]) {
            let object = try #require(entry["record"] as? [String: Any])
            let record = try ModelCapabilities.Record.parse(object)
            #expect(record.recordHash == entry["recordHash"] as? String, "\(entry["label"] ?? "")")
            // …and re-serialized, the canonical bytes are identical.
            #expect(CanonicalJSON.encode(record.canonicalPayload)
                == CanonicalJSON.encode(object.filter { $0.key != "recordHash" }))
        }
        for entry in try #require(fixture["heuristics"] as? [[String: Any]]) {
            let modelID = try #require(entry["modelID"] as? String)
            let expected = try ModelCapabilities.Record.parse(try #require(entry["record"] as? [String: Any]))
            #expect(ModelCapabilities.heuristic(modelID: modelID) == expected)
            #expect(ModelCapabilities.heuristic(modelID: modelID).recordHash == entry["recordHash"] as? String)
        }
        // The canonical form: byte-sorted keys, compact, raw UTF-8.
        #expect(CanonicalJSON.encode(["b": 1, "a": ["é": [true, NSNull()]]] as [String: Any])
            == "{\"a\":{\"é\":[true,null]},\"b\":1}")
        // Foundation's sortedKeys is NOT byte order; the canonical encoder is.
        #expect(CanonicalJSON.encode(["thinkingSwitch": 1, "thinkOpenInPrompt": 2, "thinkTokens": 3])
            == "{\"thinkOpenInPrompt\":2,\"thinkTokens\":3,\"thinkingSwitch\":1}")
    }

    @Test func theSummaryLinesGatesAndTemplateContextAreCurrent() throws {
        let fixture = try Self.load()
        var views: [String: ModelCapabilities] = [:]
        for entry in try #require(fixture["records"] as? [[String: Any]]) {
            views[entry["label"] as! String] = try ModelCapabilities.Record.parse(
                entry["record"] as! [String: Any]).effective()
        }
        views["heuristic"] = ModelCapabilities.heuristicView(modelID: Self.qwen)
        for entry in try #require(fixture["summaryLines"] as? [[String: Any]]) {
            let label = entry["label"] as! String
            let view: ModelCapabilities
            switch label {
            case "chatml-effort":
                view = try Self.recordFixture(fixture, "chatml-effort").effective(
                    path: "prompts/models/fixture--chatml-effort@" + String(repeating: "0", count: 40) + ".json")
            case "qwen-heuristic": view = views["heuristic"]!
            default: view = views[label]!
            }
            #expect(view.summaryLines == entry["lines"] as? [String], "\(label)")
        }
        for entry in try #require(fixture["gates"] as? [[String: Any]]) {
            let violations = ReasoningEffort.protocolViolations(
                effort: entry["effort"] as? String, reasoningMaxTokens: 64,
                modelID: entry["modelID"] as! String,
                capabilities: views[entry["record"] as! String]!)
            #expect(violations == entry["violations"] as? [String], "\(entry["label"] ?? "")")
        }
        for entry in try #require(fixture["templateKwargs"] as? [[String: Any]]) {
            let effort = ReasoningEffort(rawValue: entry["effort"] as! String)!
            let context = PromptRendering.thinkingContext(
                modelID: "fixture", effort: effort, capabilities: views[entry["record"] as! String]!)
            let expected = entry["kwargs"] as! [String: Any]
            let rendered = context.map { CanonicalJSON.encode($0 as [String: Any]) } ?? "{}"
            #expect(rendered == CanonicalJSON.encode(expected), "\(entry["label"] ?? "")")
        }
        let refusals = try #require(fixture["refusals"] as? [String: String])
        #expect(ReasoningEffort.effortIgnoredReason(.medium, modelID: Self.qwen) == refusals["effortIgnored"])
        #expect(ReasoningEffort.effortWithoutThinkingModeReason(.low, modelID: Self.gemma)
            == refusals["effortWithoutThinkingMode"])
        #expect(ReasoningEffort.effortRejectedReason(.high, modelID: Self.qwen38, capabilities: views["chatml-effort"]!)
            == refusals["effortRejected"])
        #expect(ReasoningEffort.effortUnprobedReason(.high, modelID: Self.qwen, capabilities: views["heuristic"]!)
            == refusals["effortUnprobed"])
        #expect(ReasoningEffort.effortAssumedAdvisory(.medium, modelID: Self.qwen) == refusals["effortAssumedAdvisory"])
        #expect(ReasoningEffort.systemPromptUnsupportedReason(modelID: "fixture/system-refused")
            == refusals["systemPromptUnsupported"])
        #expect(ModelCapabilities.heuristicAdvisory(modelID: Self.qwen) == refusals["heuristicAdvisory"])
        #expect(ExtractionRendering.effortWithoutThinkingModeError(.low, modelID: Self.gemma).message
            == refusals["extractionEffortWithoutThinkingMode"])
        #expect(ExtractionRendering.effortLevelProblemPrefix == refusals["extractionEffortLevelPrefix"])
        #expect(ReasoningEffort.vocabulary == fixture["reasoningEfforts"] as? [String])
        #expect(ModelCapabilities.effortCandidates == fixture["effortCandidates"] as? [String])
        #expect(ModelCapabilities.directory == fixture["directory"] as? String)
    }

    @Test func recordFilesRoundTripAndLookUpByRevision() async throws {
        let fixture = try Self.load()
        for entry in try #require(fixture["recordFilenames"] as? [[String: Any]]) {
            #expect(ModelCapabilitiesStore.recordFilename(
                modelID: entry["modelID"] as! String, revision: entry["revision"] as? String)
                == entry["filename"] as? String)
        }
        try await withTempRoot { root in
            let record = try Self.probe(try Self.family(fixture, "chatml-effort"))
            let written = try ModelCapabilitiesStore.write(record, root: root)
            #expect(written == "prompts/models/fixture--chatml-effort@" + String(repeating: "0", count: 40) + ".json")
            let read = try ModelCapabilitiesStore.read(root.appending(path: written))
            #expect(read == record && read.recordHash == record.recordHash)
            let view = try #require(ModelCapabilitiesStore.lookup(
                modelID: "fixture/chatml-effort", revision: String(repeating: "0", count: 40), root: root))
            #expect(view.path == written && view.isProbed)
            #expect(view.acceptedEfforts == ["low", "medium", "xhigh"])
            // Another revision answers loudly; an unknown model not at all.
            let other = try #require(ModelCapabilitiesStore.lookup(
                modelID: "fixture/chatml-effort", revision: String(repeating: "a", count: 40), root: root))
            #expect(other.advisories.contains { $0.contains("using the record for revision") })
            #expect(ModelCapabilitiesStore.lookup(modelID: "x/none", revision: nil, root: root) == nil)
            let heuristic = ModelCapabilitiesStore.resolve(modelID: Self.gemma, revision: nil, root: root)
            #expect(heuristic.source == .heuristic)
            #expect(heuristic.advisories == [ModelCapabilities.heuristicAdvisory(modelID: Self.gemma)])
        }
    }

    @Test func overridesApplyToTheEffectiveViewNeverTheDetectedBlock() throws {
        let fixture = try Self.load()
        let base = try Self.probe(try Self.family(fixture, "chatml-switch"))
        let updated = try ModelCapabilitiesStore.setOverride(
            base, field: "thinkOpenInPrompt", value: "true",
            reason: "the model always opens with <think> on its own",
            setAt: "2026-09-05T00:00:00Z")
        #expect(updated.detected.thinkOpenInPrompt == false)
        #expect(updated.effective().thinkOpenInPrompt == true)
        #expect(updated.recordHash != base.recordHash)
        // The Python engine's overridden record hashes identically.
        #expect(updated == (try Self.recordFixture(fixture, "chatml-switch-overridden")))
        let cleared = try ModelCapabilitiesStore.setOverride(updated, field: "thinkOpenInPrompt", value: "", reason: "")
        #expect(cleared.overrides.isEmpty && cleared.recordHash == base.recordHash)
        #expect(throws: ModelCapabilities.RecordError.self) {
            try ModelCapabilitiesStore.setOverride(base, field: "effortLevels", value: "x", reason: "no")
        }
        #expect(throws: ModelCapabilities.RecordError.self) {
            try ModelCapabilitiesStore.setOverride(base, field: "systemRole", value: "sideways", reason: "no")
        }
        #expect(throws: ModelCapabilities.RecordError.self) {
            try ModelCapabilitiesStore.setOverride(base, field: "systemRole", value: "systemTurn", reason: "")
        }
        let lines = ModelCapabilitiesStore.diff(old: base, new: try Self.probe(try Self.family(fixture, "chatml-effort")))
        #expect(lines.first?.hasPrefix("template sha256:") == true)
        #expect(lines.contains { $0.hasPrefix("effortLevels:") })
    }

    // MARK: - 3. the consumers

    @Test func renderingPassesOnlyTheVariablesTheTemplateReads() throws {
        let fixture = try Self.load()
        let switchOnly = try Self.probe(try Self.family(fixture, "chatml-switch")).effective()
        // A level on a switch-only template renders as `on`.
        let ignored = PromptRendering.thinkingContext(modelID: Self.qwen, effort: .medium, capabilities: switchOnly)
        #expect(ignored?.keys.sorted() == ["enable_thinking"] && ignored?["enable_thinking"] as? Bool == true)
        #expect(PromptRendering.thinkingContext(modelID: Self.qwen, effort: .off, capabilities: switchOnly)?["enable_thinking"] as? Bool == false)
        #expect(PromptRendering.qwenContext(modelID: Self.qwen, qwenThinkingEnabled: true, capabilities: switchOnly)?
            .keys.contains("reasoning_effort") == false)
        let effort = try Self.probe(try Self.family(fixture, "chatml-effort")).effective()
        let level = PromptRendering.thinkingContext(modelID: Self.qwen38, effort: .medium, capabilities: effort)
        #expect(level?["reasoning_effort"] as? String == "medium")
        #expect(PromptRendering.thinkingContext(modelID: Self.qwen38, effort: .on, capabilities: effort)?
            .keys.sorted() == ["enable_thinking"])
        let gemma = try Self.probe(try Self.family(fixture, "gemma-fold")).effective()
        #expect(PromptRendering.thinkingContext(modelID: Self.gemma, effort: .off, capabilities: gemma) == nil)
        let folded = PromptRendering.chatMessages(
            prompt: "Decide.", modelID: Self.gemma, systemPrompt: "Be brief.", capabilities: gemma)
        #expect(folded.map(\.role) == [.user] && folded[0].content == "Be brief.\n\nDecide.")
        let refused = try Self.probe(try Self.family(fixture, "system-refused")).effective()
        #expect(PromptRendering.systemPromptDelivery(modelID: "x/refuses", rawCompletion: false, capabilities: refused)
            == "undeliverable")
        #expect(PromptRendering.systemPromptDelivery(modelID: "x/refuses", rawCompletion: true, capabilities: refused)
            == "promptPrepend")
        #expect(PromptRendering.systemPromptViolations(
            systemPrompt: "Be brief.", modelID: "x/refuses", rawCompletion: false, capabilities: refused)
            == [ReasoningEffort.systemPromptUnsupportedReason(modelID: "x/refuses")])
        #expect(PromptRendering.chatMessages(
            prompt: "Decide.", modelID: "x/refuses", systemPrompt: "Be brief.", capabilities: refused)
            .map(\.content) == ["Decide."])
    }

    @Test func aRegisteredRecordDrivesTheRenderersUntilForgotten() throws {
        let fixture = try Self.load()
        defer { ModelCapabilities.forgetRegistered() }
        // Nothing registered: the id heuristic — today's rule.
        #expect(PromptRendering.hasThinkingMode(Self.qwen))
        #expect(PromptRendering.thinkingContext(modelID: Self.qwen, effort: .medium)?["reasoning_effort"] as? String == "medium")
        ModelCapabilities.register(try Self.probe(try Self.family(fixture, "chatml-switch")).effective(), for: Self.qwen)
        #expect(PromptRendering.thinkingContext(modelID: Self.qwen, effort: .medium)?.keys.sorted() == ["enable_thinking"])
        ModelCapabilities.register(try Self.probe(try Self.family(fixture, "system-refused")).effective(), for: Self.qwen)
        #expect(!PromptRendering.hasSystemRole(Self.qwen))
        #expect(ExtractionRendering.thinkingModeProblem(
            try ExtractionRendering.declared(object: ["mode": "chatTemplate", "reasoningEffort": "low"]),
            modelID: Self.qwen)?.reason.hasPrefix(ExtractionRendering.effortLevelProblemPrefix) == false)
        ModelCapabilities.forgetRegistered()
        #expect(PromptRendering.hasSystemRole(Self.qwen))
    }

