    @Test func declaringAnIgnoredLevelIsRefusedWithTheOnRepair() async throws {
        let fixture = try Self.load()
        try await withTempRoot { root in
            var record = try Self.probe(try Self.family(fixture, "chatml-switch"))
            record.modelID = Self.qwen
            record.revision = String(repeating: "c", count: 40)
            try ModelCapabilitiesStore.write(record, root: root)
            try ExperimentStore.create(name: "d", description: "", modelID: Self.qwen)
            try ExperimentStore.setModelRevision(String(repeating: "c", count: 40), experimentName: "d")
            do {
                try ExperimentStore.setSamplingProtocol(
                    reasoningEffort: "medium", reasoningMaxTokens: 64, experimentName: "d")
                Issue.record("an ignored level must refuse")
            } catch let error as ExperimentError {
                #expect(error.reason.hasPrefix(ReasoningEffort.effortIgnoredReason(.medium, modelID: Self.qwen)))
            }
            let on = try ExperimentStore.setSamplingProtocol(
                reasoningEffort: "on", reasoningMaxTokens: 64, experimentName: "d")
            #expect(on.reasoningEffort == "on")
            #expect(!ExperimentStore.verify(on).contains { $0.lowercased().contains("reasoning") })
            #expect(ExperimentStore.capabilityAdvisories(for: on).isEmpty)
            // The verb echoes the record's notes on the heuristic path.
            try ExperimentStore.create(name: "h", description: "", modelID: Self.qwen38)
            let outcome = await ExperimentCLIRunner(sink: .discarding).run(
                namespace: "experiment",
                ["set-sampling", "h", "--reasoning-effort", "medium", "--reasoning-max-tokens", "64"])
            #expect(outcome.envelope.exitCode == 0)
            #expect(outcome.envelope.advisories?.contains { $0.code == CLIAdvisory.modelCapabilities.rawValue } == true)
        }
    }

