    @Test func aFrozenStudyKeepsVerifyingAndIsAdvisedInstead() async throws {
        let fixture = try Self.load()
        try await withTempRoot { root in
            var record = try Self.probe(try Self.family(fixture, "chatml-switch"))
            record.modelID = Self.qwen
            record.revision = String(repeating: "c", count: 40)
            try ModelCapabilitiesStore.write(record, root: root)
            var manifest = try ExperimentStore.create(name: "d", description: "", modelID: Self.qwen)
            manifest.modelRevision = String(repeating: "c", count: 40)
            manifest.reasoningEffort = "medium"
            manifest.reasoningMaxTokens = 64
            manifest.status = .frozen
            // A frozen manifest is read-only to the store: the flip is a
            // plain file write, exactly as the Python twin does it.
            func writeManifest(_ manifest: ExperimentManifest) throws {
                let encoder = JSONEncoder()
                encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
                try encoder.encode(manifest).write(to: ExperimentStore.manifestURL("d"))
            }
            try writeManifest(manifest)
            let frozen = try ExperimentStore.load(name: "d")
            #expect(!ExperimentStore.verify(frozen).contains { $0.lowercased().contains("reasoning") })
            #expect(ExperimentStore.capabilityAdvisories(for: frozen)
                .contains(ReasoningEffort.effortIgnoredReason(.medium, modelID: Self.qwen)))
            manifest.status = .draft
            try writeManifest(manifest)
            #expect(ExperimentStore.verify(try ExperimentStore.load(name: "d"))
                .contains(ReasoningEffort.effortIgnoredReason(.medium, modelID: Self.qwen)))
            // The preregistration prints the record.
            let text = ExperimentStore.preregistrationMarkdown(frozen)
            #expect(text.contains("- **Model capabilities:** source probe, record `prompts/models/"))
            #expect(text.contains("- **Thinking switch:** supported, opening tag in prompt false"))
            #expect(text.contains("- **Reasoning effort levels:** low ignored, medium ignored, high ignored, xhigh ignored"))
        }
    }

    @Test func runsStampTheRecordTheyRenderedUnder() async throws {
        let fixture = try Self.load()
        try await withTempRoot { root in
            var record = try Self.probe(try Self.family(fixture, "chatml-switch"))
            record.modelID = Self.qwen
            record.revision = String(repeating: "c", count: 40)
            let written = try ModelCapabilitiesStore.write(record, root: root)
            var manifest = try ExperimentStore.create(name: "d", description: "", modelID: Self.qwen)
            manifest.modelRevision = String(repeating: "c", count: 40)
            manifest.reasoningEffort = "medium"
            manifest.reasoningMaxTokens = 64
            let notes = ExperimentTasks.runStructuredNotes(experiment: manifest, task: "run", sampling: nil)
            let stamp = try #require(notes["modelCapabilities"] as? [String: Any])
            #expect(stamp["source"] as? String == "probe")
            #expect(stamp["record"] as? String == written)
            #expect(stamp["recordHash"] as? String == record.recordHash)
            #expect((stamp["effortLevels"] as? [String: String])?["medium"] == "ignored")
            // analyze renders nothing and stamps nothing.
            #expect(ExperimentTasks.runStructuredNotes(experiment: manifest, task: "analyze", sampling: nil)["modelCapabilities"] == nil)
            let advisories = ExperimentTasks.capabilityRunAdvisories(
                experiment: manifest, capabilities: record.effective(path: written))
            #expect(advisories.contains(ReasoningEffort.effortIgnoredReason(.medium, modelID: Self.qwen)))
        }
    }

    @Test func theModelVerbsShowAndOverrideTheRecord() async throws {
        let fixture = try Self.load()
        try await withTempRoot { root in
            let shown = await ExperimentCLIRunner(sink: .discarding).run(
                namespace: "model", ["capabilities", Self.qwen, "--json"])
            #expect(shown.envelope.exitCode == 0)
            #expect(shown.envelope.advisories?.contains { $0.code == CLIAdvisory.modelCapabilities.rawValue } == true)
            let missing = await ExperimentCLIRunner(sink: .discarding).run(
                namespace: "model", ["set-capability", Self.qwen, "systemRole", "systemTurn", "--reason", "x", "--json"])
            #expect(missing.envelope.exitCode == 66)
            var record = try Self.probe(try Self.family(fixture, "chatml-switch"))
            record.modelID = Self.qwen
            record.revision = String(repeating: "c", count: 40)
            try ModelCapabilitiesStore.write(record, root: root)
            let overridden = await ExperimentCLIRunner(sink: .discarding).run(
                namespace: "model",
                ["set-capability", Self.qwen, "thinkOpenInPrompt", "true", "--reason", "always opens", "--json"])
            #expect(overridden.envelope.exitCode == 0, "\(overridden)")
            let view = try #require(ModelCapabilitiesStore.lookup(modelID: Self.qwen, revision: nil, root: root))
            #expect(view.thinkOpenInPrompt == true && view.overrides["thinkOpenInPrompt"]?.reason == "always opens")
            let refused = await ExperimentCLIRunner(sink: .discarding).run(
                namespace: "model", ["set-capability", Self.qwen, "systemRole", "sideways", "--reason", "x"])
            #expect(refused.envelope.exitCode == 64)
        }
    }
}
